/* Upload streaming: per-frame CPU -> GPU uploads, the way engines stream
 * constants, geometry and textures. CPU time includes writing the data
 * (memcpy from a 64 MB pool of pre-generated bytes), as it does in a game.
 *
 *   buffer_4k_x256    256 x 4 KB updates through a persistently mapped
 *                     staging ring, one vkCmdCopyBuffer each, to scattered
 *                     offsets of a device-local buffer
 *   buffer_bulk_32m   one 32 MB staging copy (a streamed mesh or world chunk)
 *   image_tiles_x64   64 128x128 RGBA8 tiles into a 2048x2048 atlas, one
 *                     vkCmdCopyBufferToImage each, with layout transitions
 *   image_mips_2048   a whole 2048x2048 RGBA8 texture with its 12 mips
 *   direct_4k_x256    the 256 updates written straight into host-visible
 *                     device-local memory (unified memory), no copies
 *   map_flush_4k_x256 per frame vkMapMemory, writes, one
 *                     vkFlushMappedMemoryRanges range per update,
 *                     vkUnmapMemory (non-coherent memory when available),
 *                     then the copies
 *
 * The first frame of each configuration is read back on the GPU side and
 * compared byte for byte with what was written.
 */
#include "bench_vk.h"

#define POOL_BYTES (64u << 20)
#define DST_BYTES (64u << 20)
#define ATLAS 2048
#define TILE 128
#define ATLAS_CELLS ((ATLAS / TILE) * (ATLAS / TILE))
#define MIPS 12
#define SLOTS 4096 /* 4 KB slots in the destination for scattered updates */

enum mode { MODE_BUFFER_COPIES, MODE_BUFFER_BULK, MODE_IMAGE_TILES, MODE_IMAGE_MIPS, MODE_DIRECT, MODE_MAP_FLUSH };

struct config {
    const char *name;
    enum mode mode;
    uint32_t regions;
    uint32_t region_bytes; /* buffer modes */
    int frames;
};

static const struct config configs[] = {
    { "buffer_4k_x256", MODE_BUFFER_COPIES, 256, 4096, 300 },
    { "buffer_bulk_32m", MODE_BUFFER_BULK, 1, 32u << 20, 100 },
    { "image_tiles_x64", MODE_IMAGE_TILES, 64, TILE * TILE * 4, 200 },
    { "image_mips_2048", MODE_IMAGE_MIPS, MIPS, 0, 100 },
    { "direct_4k_x256", MODE_DIRECT, 256, 4096, 300 },
    { "map_flush_4k_x256", MODE_MAP_FLUSH, 256, 4096, 300 },
};

struct scene {
    struct bench_vk *vk;
    const struct config *cfg;
    uint8_t *pool;
    VkDeviceSize frame_bytes;        /* staging bytes per frame (with mip padding) */
    VkDeviceSize mip_offset[MIPS];   /* image_mips: staging offset of each mip */
    struct bench_buffer staging;     /* persistently mapped ring, one region per slot */
    struct bench_buffer flush_staging; /* map_flush: not persistently mapped */
    int flush_coherent;
    struct bench_buffer direct;      /* host-visible device-local, one region per slot */
    struct bench_buffer dst, readback;
    struct bench_image atlas, texture;
    uint32_t verify_index;
};

static VkDeviceSize payload_bytes(const struct config *cfg)
{
    VkDeviceSize bytes = 0;
    uint32_t m;
    if (cfg->mode != MODE_IMAGE_MIPS)
        return (VkDeviceSize)cfg->regions * cfg->region_bytes;
    for (m = 0; m < MIPS; m++)
        bytes += (VkDeviceSize)(ATLAS >> m) * (ATLAS >> m) * 4;
    return bytes;
}

/* Where frame f's data starts in the pool. */
static size_t pool_base(uint32_t f, VkDeviceSize bytes)
{
    return (size_t)(((uint64_t)f * 2654435761u) % (POOL_BYTES - bytes)) & ~(size_t)255;
}

/* Destination slot of update r: a permutation, so updates never overlap. */
static VkDeviceSize slot_offset(uint32_t r)
{
    return (VkDeviceSize)((r * 1031u) % SLOTS) * 4096;
}

/* Atlas cell of tile t in frame f. */
static uint32_t atlas_cell(uint32_t f, uint32_t t)
{
    return (t + f * 64u) % ATLAS_CELLS;
}

static void copy_barrier(VkCommandBuffer cmd)
{
    /* Earlier frames' copies to the same destination come first. */
    bench_memory_barrier(cmd, VK_PIPELINE_STAGE_2_COPY_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT,
                         VK_PIPELINE_STAGE_2_COPY_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT);
}

static void consume_barrier(VkCommandBuffer cmd)
{
    /* Make the uploads visible to the shaders that would use them. */
    bench_memory_barrier(cmd, VK_PIPELINE_STAGE_2_COPY_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT,
                         VK_PIPELINE_STAGE_2_VERTEX_SHADER_BIT | VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT |
                             VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT,
                         VK_ACCESS_2_SHADER_READ_BIT);
}

static void record_buffer_copies(struct scene *s, const struct bench_frame *f, VkBuffer src, VkDeviceSize src_base)
{
    uint32_t r;
    copy_barrier(f->cmd);
    for (r = 0; r < s->cfg->regions; r++) {
        VkBufferCopy region = { src_base + (VkDeviceSize)r * s->cfg->region_bytes, slot_offset(r), s->cfg->region_bytes };
        vkd.CmdCopyBuffer(f->cmd, src, s->dst.buffer, 1, &region);
    }
    consume_barrier(f->cmd);
}

static void record(void *user, const struct bench_frame *f)
{
    struct scene *s = user;
    struct bench_vk *vk = s->vk;
    const struct config *cfg = s->cfg;
    VkCommandBuffer cmd = f->cmd;
    VkDeviceSize bytes = payload_bytes(cfg), slot_base = (VkDeviceSize)f->slot * s->frame_bytes;
    const uint8_t *src = s->pool + pool_base(f->index, bytes);
    uint8_t *staging = (uint8_t *)s->staging.map + slot_base;
    uint32_t r, m;

    if (f->verify)
        s->verify_index = f->index;

    switch (cfg->mode) {
    case MODE_BUFFER_COPIES:
        for (r = 0; r < cfg->regions; r++)
            memcpy(staging + (size_t)r * cfg->region_bytes, src + (size_t)r * cfg->region_bytes, cfg->region_bytes);
        record_buffer_copies(s, f, s->staging.buffer, slot_base);
        break;

    case MODE_BUFFER_BULK: {
        VkBufferCopy region = { slot_base, 0, bytes };
        memcpy(staging, src, (size_t)bytes);
        copy_barrier(cmd);
        vkd.CmdCopyBuffer(cmd, s->staging.buffer, s->dst.buffer, 1, &region);
        consume_barrier(cmd);
        break;
    }

    case MODE_IMAGE_TILES:
        memcpy(staging, src, (size_t)bytes);
        bench_image_barrier(cmd, &s->atlas, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
                            VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
                            VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COPY_BIT, 0,
                            VK_PIPELINE_STAGE_2_COPY_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT);
        for (r = 0; r < cfg->regions; r++) {
            uint32_t cell = atlas_cell(f->index, r);
            VkBufferImageCopy region = {
                .bufferOffset = slot_base + (VkDeviceSize)r * cfg->region_bytes,
                .imageSubresource = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1 },
                .imageOffset = { (int32_t)(cell % (ATLAS / TILE)) * TILE, (int32_t)(cell / (ATLAS / TILE)) * TILE, 0 },
                .imageExtent = { TILE, TILE, 1 },
            };
            vkd.CmdCopyBufferToImage(cmd, s->staging.buffer, s->atlas.image, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1,
                                     &region);
        }
        bench_image_barrier(cmd, &s->atlas, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
                            VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL, VK_PIPELINE_STAGE_2_COPY_BIT,
                            VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT,
                            VK_ACCESS_2_SHADER_SAMPLED_READ_BIT);
        break;

    case MODE_IMAGE_MIPS: {
        VkBufferImageCopy regions[MIPS];
        size_t offset = 0;
        for (m = 0; m < MIPS; m++) {
            size_t size = (size_t)(ATLAS >> m) * (ATLAS >> m) * 4;
            memcpy(staging + s->mip_offset[m], src + offset, size);
            offset += size;
            memset(&regions[m], 0, sizeof(regions[m]));
            regions[m].bufferOffset = slot_base + s->mip_offset[m];
            regions[m].imageSubresource = (VkImageSubresourceLayers){ VK_IMAGE_ASPECT_COLOR_BIT, m, 0, 1 };
            regions[m].imageExtent = (VkExtent3D){ ATLAS >> m, ATLAS >> m, 1 };
        }
        /* The whole texture is replaced: its old contents can go. */
        bench_image_barrier(cmd, &s->texture, VK_IMAGE_LAYOUT_UNDEFINED, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
                            VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COPY_BIT, 0,
                            VK_PIPELINE_STAGE_2_COPY_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT);
        vkd.CmdCopyBufferToImage(cmd, s->staging.buffer, s->texture.image, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
                                 MIPS, regions);
        bench_image_barrier(cmd, &s->texture, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,
                            VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL, VK_PIPELINE_STAGE_2_COPY_BIT,
                            VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT,
                            VK_ACCESS_2_SHADER_SAMPLED_READ_BIT);
        break;
    }

    case MODE_DIRECT: {
        uint8_t *dst = (uint8_t *)s->direct.map + (size_t)f->slot * SLOTS * 4096;
        for (r = 0; r < cfg->regions; r++)
            memcpy(dst + slot_offset(r), src + (size_t)r * cfg->region_bytes, cfg->region_bytes);
        break;
    }

    case MODE_MAP_FLUSH: {
        VkMappedMemoryRange ranges[256];
        void *map = NULL;
        BENCH_VK(vkd.MapMemory(vk->device, s->flush_staging.memory, slot_base, bytes, 0, &map));
        for (r = 0; r < cfg->regions; r++) {
            memcpy((uint8_t *)map + (size_t)r * cfg->region_bytes, src + (size_t)r * cfg->region_bytes,
                   cfg->region_bytes);
            ranges[r].sType = VK_STRUCTURE_TYPE_MAPPED_MEMORY_RANGE;
            ranges[r].pNext = NULL;
            ranges[r].memory = s->flush_staging.memory;
            ranges[r].offset = slot_base + (VkDeviceSize)r * cfg->region_bytes;
            ranges[r].size = cfg->region_bytes;
        }
        BENCH_VK(vkd.FlushMappedMemoryRanges(vk->device, cfg->regions, ranges));
        vkd.UnmapMemory(vk->device, s->flush_staging.memory);
        record_buffer_copies(s, f, s->flush_staging.buffer, slot_base);
        break;
    }
    }

    if (!f->verify)
        return;
    /* Read back what the GPU now has. */
    if (cfg->mode == MODE_IMAGE_TILES || cfg->mode == MODE_IMAGE_MIPS) {
        struct bench_image *img = cfg->mode == MODE_IMAGE_TILES ? &s->atlas : &s->texture;
        VkBufferImageCopy regions[MIPS];
        uint32_t count = cfg->mode == MODE_IMAGE_TILES ? 1 : MIPS;
        for (m = 0; m < count; m++) {
            memset(&regions[m], 0, sizeof(regions[m]));
            regions[m].bufferOffset = s->mip_offset[m];
            regions[m].imageSubresource = (VkImageSubresourceLayers){ VK_IMAGE_ASPECT_COLOR_BIT, m, 0, 1 };
            regions[m].imageExtent = (VkExtent3D){ ATLAS >> m, ATLAS >> m, 1 };
        }
        bench_image_barrier(cmd, img, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                            VK_PIPELINE_STAGE_2_COPY_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_PIPELINE_STAGE_2_COPY_BIT,
                            VK_ACCESS_2_TRANSFER_READ_BIT);
        vkd.CmdCopyImageToBuffer(cmd, img->image, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, s->readback.buffer, count,
                                 regions);
        bench_image_barrier(cmd, img, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
                            VK_PIPELINE_STAGE_2_COPY_BIT, 0, VK_PIPELINE_STAGE_2_COPY_BIT, 0);
    } else {
        VkBuffer from = cfg->mode == MODE_DIRECT ? s->direct.buffer : s->dst.buffer;
        VkBufferCopy region = { cfg->mode == MODE_DIRECT ? (VkDeviceSize)f->slot * SLOTS * 4096 : 0, 0,
                                cfg->mode == MODE_BUFFER_BULK ? bytes : (VkDeviceSize)SLOTS * 4096 };
        bench_memory_barrier(cmd, VK_PIPELINE_STAGE_2_COPY_BIT | VK_PIPELINE_STAGE_2_HOST_BIT,
                             VK_ACCESS_2_TRANSFER_WRITE_BIT | VK_ACCESS_2_HOST_WRITE_BIT, VK_PIPELINE_STAGE_2_COPY_BIT,
                             VK_ACCESS_2_TRANSFER_READ_BIT);
        vkd.CmdCopyBuffer(cmd, from, s->readback.buffer, 1, &region);
    }
    bench_memory_barrier(cmd, VK_PIPELINE_STAGE_2_COPY_BIT, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_PIPELINE_STAGE_2_HOST_BIT,
                         VK_ACCESS_2_HOST_READ_BIT);
}

static int verify(struct scene *s)
{
    const struct config *cfg = s->cfg;
    const uint8_t *got = s->readback.map;
    const uint8_t *src = s->pool + pool_base(s->verify_index, payload_bytes(cfg));
    uint32_t r, m, y;

    switch (cfg->mode) {
    case MODE_BUFFER_BULK:
        if (memcmp(got, src, (size_t)payload_bytes(cfg)) != 0) {
            bench_error(cfg->name, "destination differs from the uploaded data");
            return 0;
        }
        return 1;
    case MODE_IMAGE_TILES:
        for (r = 0; r < cfg->regions; r++) {
            uint32_t cell = atlas_cell(s->verify_index, r);
            uint32_t x0 = (cell % (ATLAS / TILE)) * TILE, y0 = (cell / (ATLAS / TILE)) * TILE;
            for (y = 0; y < TILE; y++)
                if (memcmp(got + ((size_t)(y0 + y) * ATLAS + x0) * 4, src + (size_t)r * cfg->region_bytes + (size_t)y * TILE * 4,
                           TILE * 4) != 0) {
                    bench_error(cfg->name, "tile %u (atlas cell %u) row %u differs", r, cell, y);
                    return 0;
                }
        }
        return 1;
    case MODE_IMAGE_MIPS: {
        size_t offset = 0;
        for (m = 0; m < MIPS; m++) {
            size_t size = (size_t)(ATLAS >> m) * (ATLAS >> m) * 4;
            if (memcmp(got + s->mip_offset[m], src + offset, size) != 0) {
                bench_error(cfg->name, "mip %u differs", m);
                return 0;
            }
            offset += size;
        }
        return 1;
    }
    default:
        for (r = 0; r < cfg->regions; r++)
            if (memcmp(got + slot_offset(r), src + (size_t)r * cfg->region_bytes, cfg->region_bytes) != 0) {
                bench_error(cfg->name, "update %u (offset %llu) differs", r, (unsigned long long)slot_offset(r));
                return 0;
            }
        return 1;
    }
}

static void setup(struct scene *s)
{
    struct bench_vk *vk = s->vk;
    VkBufferUsageFlags transfer = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT;
    VkDeviceSize max_frame = 0, offset = 0;
    uint32_t type, i, m;
    uint64_t seed = 0x5EED5EEDull;
    VkCommandBuffer cmd;

    /* Source data. */
    s->pool = bench_alloc(POOL_BYTES);
    for (i = 0; i < POOL_BYTES / 4; i++)
        ((uint32_t *)s->pool)[i] = bench_rand(&seed);

    /* Mip layout in staging (256-byte aligned), and the largest frame. */
    for (m = 0; m < MIPS; m++) {
        s->mip_offset[m] = offset;
        offset += ((VkDeviceSize)(ATLAS >> m) * (ATLAS >> m) * 4 + 255) & ~(VkDeviceSize)255;
    }
    max_frame = offset;
    for (i = 0; i < sizeof(configs) / sizeof(configs[0]); i++)
        if (configs[i].mode != MODE_IMAGE_MIPS && payload_bytes(&configs[i]) > max_frame)
            max_frame = payload_bytes(&configs[i]);
    s->frame_bytes = max_frame;

    bench_buffer_create(vk, &s->staging, max_frame * BENCH_FRAMES_IN_FLIGHT, VK_BUFFER_USAGE_TRANSFER_SRC_BIT,
                        BENCH_HOST, 0);
    bench_buffer_create(vk, &s->dst, DST_BYTES, transfer | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, 0, BENCH_DEVICE_LOCAL);
    bench_buffer_create(vk, &s->readback, DST_BYTES, VK_BUFFER_USAGE_TRANSFER_DST_BIT, BENCH_HOST,
                        VK_MEMORY_PROPERTY_HOST_CACHED_BIT);
    bench_buffer_create(vk, &s->direct, (VkDeviceSize)SLOTS * 4096 * BENCH_FRAMES_IN_FLIGHT,
                        VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, BENCH_HOST,
                        BENCH_DEVICE_LOCAL);

    /* map_flush prefers memory that needs flushing; it maps per frame. */
    {
        VkBufferCreateInfo info = {
            .sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,
            .size = max_frame * BENCH_FRAMES_IN_FLIGHT,
            .usage = VK_BUFFER_USAGE_TRANSFER_SRC_BIT,
            .sharingMode = VK_SHARING_MODE_EXCLUSIVE,
        };
        VkMemoryRequirements req;
        memset(&s->flush_staging, 0, sizeof(s->flush_staging));
        memset(&req, 0, sizeof(req));
        BENCH_VK(vkd.CreateBuffer(vk->device, &info, NULL, &s->flush_staging.buffer));
        vkd.GetBufferMemoryRequirements(vk->device, s->flush_staging.buffer, &req);
        type = bench_memory_type(vk, req.memoryTypeBits, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT,
                                 VK_MEMORY_PROPERTY_HOST_CACHED_BIT, VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
        s->flush_coherent = type == UINT32_MAX;
        s->flush_staging.memory = bench_allocate(vk, &req, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT,
                                                 s->flush_coherent ? 0 : VK_MEMORY_PROPERTY_HOST_CACHED_BIT,
                                                 s->flush_coherent ? 0 : VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                                                 &s->flush_staging.flags);
        BENCH_VK(vkd.BindBufferMemory(vk->device, s->flush_staging.buffer, s->flush_staging.memory, 0));
        s->flush_staging.size = info.size;
    }

    /* The atlas starts out defined (and sampled); the texture is replaced whole. */
    bench_image_create(vk, &s->atlas, VK_FORMAT_R8G8B8A8_UNORM, ATLAS, ATLAS, 1, VK_SAMPLE_COUNT_1_BIT,
                       VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT, 0);
    bench_image_create(vk, &s->texture, VK_FORMAT_R8G8B8A8_UNORM, ATLAS, ATLAS, MIPS, VK_SAMPLE_COUNT_1_BIT,
                       VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT, 0);
    cmd = bench_cmd_begin(vk);
    bench_image_barrier(cmd, &s->atlas, VK_IMAGE_LAYOUT_UNDEFINED, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
                        VK_PIPELINE_STAGE_2_NONE, 0, VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT,
                        VK_ACCESS_2_SHADER_SAMPLED_READ_BIT);
    bench_image_barrier(cmd, &s->texture, VK_IMAGE_LAYOUT_UNDEFINED, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,
                        VK_PIPELINE_STAGE_2_NONE, 0, VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT,
                        VK_ACCESS_2_SHADER_SAMPLED_READ_BIT);
    bench_cmd_finish(vk, cmd);
}

static void teardown(struct scene *s)
{
    struct bench_vk *vk = s->vk;
    vkd.DeviceWaitIdle(vk->device);
    bench_buffer_destroy(vk, &s->staging);
    bench_buffer_destroy(vk, &s->flush_staging);
    bench_buffer_destroy(vk, &s->direct);
    bench_buffer_destroy(vk, &s->dst);
    bench_buffer_destroy(vk, &s->readback);
    bench_image_destroy(vk, &s->atlas);
    bench_image_destroy(vk, &s->texture);
    free(s->pool);
}

int main(void)
{
    struct bench_vk vk;
    struct bench_loop loop;
    struct scene *s;
    size_t c;

    bench_begin("upload_streaming");
    bench_vk_init(&vk, BENCH_NEED_SYNC2);
    s = bench_alloc(sizeof(*s));
    s->vk = &vk;
    setup(s);
    bench_loop_init(&loop, &vk, 1000);

    for (c = 0; c < sizeof(configs) / sizeof(configs[0]); c++) {
        const struct config *cfg = &configs[c];
        int frames = bench_frames(cfg->frames);
        double bytes = (double)payload_bytes(cfg), cpu_median, gpu_median;
        struct bench_json j;

        if (!bench_selected(cfg->name))
            continue;
        bench_config = cfg->name;
        if (cfg->mode == MODE_DIRECT && !(s->direct.flags & BENCH_DEVICE_LOCAL)) {
            bench_skip(cfg->name, "no host-visible device-local memory");
            continue;
        }
        s->cfg = cfg;
        bench_loop_verify(&loop, record, s);
        if (!verify(s))
            continue;
        bench_loop_run(&loop, record, s, 10, frames < 1000 ? frames : 1000);
        cpu_median = bench_loop_cpu_median(&loop);
        gpu_median = bench_loop_gpu_median(&loop);

        bench_json_begin(&j, cfg->name);
        bench_json_int(&j, "bytes_per_frame", (long long)bytes);
        bench_json_int(&j, "uploads_per_frame", cfg->regions);
        if (cfg->mode == MODE_MAP_FLUSH)
            bench_json_bool(&j, "coherent", s->flush_coherent);
        bench_loop_report(&loop, &j);
        bench_json_num(&j, "cpu_gb_per_s", bytes / cpu_median / 1000.0);
        if (cfg->mode != MODE_DIRECT && gpu_median > 0.0)
            bench_json_num(&j, "gpu_gb_per_s", bytes / gpu_median / 1000.0);
        bench_json_end(&j);
    }
    bench_config = NULL;

    bench_loop_destroy(&loop);
    teardown(s);
    free(s);
    bench_vk_destroy(&vk);
    return bench_exit_code();
}
